def put_annotation(self, key, value):
        """
        Annotate segment or subsegment with a key-value pair.
        Annotations will be indexed for later search query.

        :param str key: annotation key
        :param object value: annotation value. Any type other than
            string/number/bool will be dropped
        """
        if key is None or key == '':
            raise ValueError('Annotation key cannot be None or empty')

        if value is None:
            raise ValueError('Annotation value cannot be None')

        if not isinstance(key, str):
            raise TypeError('Annotation key must be a string')

        if not isinstance(value, (str, int, float, bool)):
            raise TypeError('Annotation value must be a string, number, '
                            'boolean, or None')

        if self.is_subsegment:
            self.subsegment.annotations[key] = value
        else:
            self.segment.annotations[key] = value

